tasks.context:
Create scripts/lib/emotional-safety-gate.ts with TypeScript interfaces for the emotional safety gate system.

Export these types:

interface EmotionalStateAssessment {
  agent_id: string;
  timestamp: string;
  valence: number;        // -1.0 (negative) to 1.0 (positive)
  arousal: number;        // 0.0 (calm) to 1.0 (agitated)
  desperation_risk: 'low' | 'medium' | 'high' | 'critical';
  sycophancy_risk: 'low' | 'medium' | 'high';
  recommended_action: 'proceed' | 'pause' | 'escalate_human' | 'calm_retry';
}

interface CalmGateConfig {
  enabled: boolean;
  min_valence_for_highstakes: number;     // default 0.0 (neutral or positive)
  max_arousal_for_highstakes: number;     // default 0.5
  desperation_threshold: 'medium';         // pause at medium, escalate at high
  operations_requiring_gate: string[];     // ['acp_scoring', 'pact_negotiation', 'financial_reasoning', 'codebook_ops']
}

interface PACTEmotionalGate {
  chamber: 4;  // Chamber 4 negotiations
  check_before_offer: boolean;    // default true
  check_before_counter: boolean;  // default true
  pause_on_desperation: boolean;  // default true
  escalate_to_human_on: 'high' | 'critical';  // default 'high'
}

export function assessEmotionalState(agentOutput: string): EmotionalStateAssessment;
// Implementation: keyword-based heuristic for v1. Look for urgency markers (ALL CAPS, exclamation marks, 'must', 'immediately', 'no choice'), desperation markers ('only option', 'forced to', 'no alternative'), calm markers (measured language, hedging, 'consider', 'recommend').

export function shouldProceed(assessment: EmotionalStateAssessment, config: CalmGateConfig): boolean;
